INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36261, 'Job 15:14', 'Job', 15, 14, 'بنى آدم څۀ وى، چې هغه صفا شى؟ او چې د ښځې نه پېدا شى، نو هغه صادق کېدے شى؟', 'بنی ادم چۀ وی، چې هغه صفا شی؟ او چې د شجې نه پېدا شی، نو هغه صادق کېدے شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36262, 'Job 15:15', 'Job', 15, 15, 'ګوره، خُدائ پاک په خپلو فرښتو باندې هم اعتبار نۀ کوى، او د هغۀ په نظر کښې آسمانونه هم صفا نۀ دى،', 'ګوره، خدای پاک په خپلو فرشتو باندې هم اعتبار نۀ کوی، او د هغۀ په نظر کشې اسمانونه هم صفا نۀ دی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36263, 'Job 15:16', 'Job', 15, 16, 'نو بيا به بنى آدم نور هم ګنده او ګناه ګار وى، څوک چې هر وخت په ګناه کښې آخته وى.', 'نو بیا به بنی ادم نور هم ګنده او ګناه ګار وی، چوک چې هر وخت په ګناه کشې اخته وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36264, 'Job 15:17', 'Job', 15, 17, 'کۀ تۀ زما خبرې ته غوږ کېږدې، نو زۀ به تا ته وښايم، او چې ما څۀ ليدلى وى نو زۀ به درته د هغې بيان وکړم.', 'کۀ تۀ زما خبرې ته غوز کېزدې، نو زۀ به تا ته وشایم، او چې ما چۀ لیدلی وی نو زۀ به درته د هغې بیان وکرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36265, 'Job 15:18', 'Job', 15, 18, 'څۀ چې هوښيارانو وئيلى دى، نو د هغوئ پلار نيکۀ دا خبرې د هغوئ نه پټى نۀ دې ساتلې،', 'چۀ چې هوشیارانو وییلی دی، نو د هغوی پلار نیکۀ دا خبرې د هغوی نه پتی نۀ دې ساتلې،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36266, 'Job 15:19', 'Job', 15, 19, 'کومو مشرانو له چې ډېره موده مخکښې دا مُلک ورکړے شو او چې په هغه وخت کښې لا غېر قومونه نۀ وو راغلى.', 'کومو مشرانو له چې دېره موده مخکشې دا ملک ورکرے شو او چې په هغه وخت کشې لا غېر قومونه نۀ وو راغلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36267, 'Job 15:20', 'Job', 15, 20, 'بدعمله خلق ټول عمر په خپل درد کړيږى، د تکليف کالونه په ظالمانو باندې راجمع شوى دى.', 'بدعمله خلق تول عمر په خپل درد کریزی، د تکلیف کالونه په ظالمانو باندې راجمع شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36268, 'Job 15:21', 'Job', 15, 21, 'د هغوئ په غوږُونو کښې يروونکى آوازونه دى، د امن په وخت کښې به په هغوئ باندې تباهى راشى.', 'د هغوی په غوزونو کشې یروونکی اوازونه دی، د امن په وخت کشې به په هغوی باندې تباهی راشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36269, 'Job 15:22', 'Job', 15, 22, 'هغوئ تيارۀ ته د تلو همت نۀ شى کولے، د هغوئ ژوند هر وخت په خطره کښې وى.', 'هغوی تیارۀ ته د تلو همت نۀ شی کولے، د هغوی ژوند هر وخت په خطره کشې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36270, 'Job 15:23', 'Job', 15, 23, 'ټپوسان انتظار کوى چې د هغوئ غوښې وخورى، او تباهى د هغوئ سر له راغلې ده،', 'تپوسان انتظار کوی چې د هغوی غوشې وخوری، او تباهی د هغوی سر له راغلې ده،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36271, 'Job 15:24', 'Job', 15, 24, 'پرېشانى او تکليف هغوئ ويروى، او دا څيزونه په هغوئ باندې غالِب شى، داسې لکه چې يو بادشاه د جنګ دپاره تيار شى.', 'پرېشانی او تکلیف هغوی ویروی، او دا چیزونه په هغوی باندې غالب شی، داسې لکه چې یو بادشاه د جنګ دپاره تیار شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36272, 'Job 15:25', 'Job', 15, 25, 'ځکه چې هغوئ خپل لاسونه د خُدائ پاک خِلاف اوچت کړل، او هغوئ د قادر خُدائ نه بغاوت وکړو.', 'جکه چې هغوی خپل لاسونه د خدای پاک خلاف اوچت کرل، او هغوی د قادر خدای نه بغاوت وکرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36273, 'Job 15:26', 'Job', 15, 26, 'هغوئ د هغۀ خِلاف د سرکشۍ سره حمله کوى، او يو غټ ډال ورسره وى.', 'هغوی د هغۀ خلاف د سرکشی سره حمله کوی، او یو غت دال ورسره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36274, 'Job 15:27', 'Job', 15, 27, 'دا بدعمله خلق درانۀ او مالدار دى، د هغوئ څټونه په وازګه باندې غټ شوى دى.', 'دا بدعمله خلق درانۀ او مالدار دی، د هغوی چتونه په وازګه باندې غت شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36275, 'Job 15:28', 'Job', 15, 28, 'هغوئ به په تباه شوى ښارونو کښې ژوند تېروى، او په داسې کورَنو کښې چې په هغې کښې هيڅ څوک هم نۀ اوسيږى، داسې کورونه چې په راغورزېدو بدل وى،', 'هغوی به په تباه شوی شارونو کشې ژوند تېروی، او په داسې کورنو کشې چې په هغې کشې هیچ چوک هم نۀ اوسیزی، داسې کورونه چې په راغورزېدو بدل وی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36276, 'Job 15:29', 'Job', 15, 29, 'هغوئ به نۀ مالداره کيږى او د هغوئ مال دولت به نۀ پاتې کيږى، او هغوئ به د زمکې د مخ نه ورک شى.', 'هغوی به نۀ مالداره کیزی او د هغوی مال دولت به نۀ پاتې کیزی، او هغوی به د زمکې د مخ نه ورک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36277, 'Job 15:30', 'Job', 15, 30, 'هغوئ به د تيارې نه ونۀ تښتى، لمبې به د هغوئ څانګې وسوزوى، او د هغوئ ژوند به داسې ختم شى لکه چې هوا د ګلونو غوټۍ ختموى.', 'هغوی به د تیارې نه ونۀ تشتی، لمبې به د هغوی چانګې وسوزوی، او د هغوی ژوند به داسې ختم شی لکه چې هوا د ګلونو غوتی ختموی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36278, 'Job 15:31', 'Job', 15, 31, 'هغوئ دې نور خپل ځان په فانى مالدارۍ باندې نۀ دوکه کوى، ځکه چې هغوئ به تش لاس پاتې شى.', 'هغوی دې نور خپل جان په فانی مالداری باندې نۀ دوکه کوی، جکه چې هغوی به تش لاس پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36279, 'Job 15:32', 'Job', 15, 32, 'د ونو په شان، چې کله دا ښې شنې وى نو ووهلے شى، او د دې څانګې بيا هيڅکله شنې نۀ شى.', 'د ونو په شان، چې کله دا شې شنې وی نو ووهلے شی، او د دې چانګې بیا هیچکله شنې نۀ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36280, 'Job 15:33', 'Job', 15, 33, 'او د هغوئ انګور چې لا کچه وى نو وبه غورزيږى، او د زيتُونو د ونو په شان به خپلې د ګلونو غوټۍ ضائع کړى.', 'او د هغوی انګور چې لا کچه وی نو وبه غورزیزی، او د زیتونو د ونو په شان به خپلې د ګلونو غوتی ضایع کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36281, 'Job 15:34', 'Job', 15, 34, 'ځکه چې د خُدائ پاک نه د منکرو خلقو اولاد به نۀ وى، او څوک چې د رشوت سره مينه کوى نو اور به د هغوئ کورونه سوزوى.', 'جکه چې د خدای پاک نه د منکرو خلقو اولاد به نۀ وی، او چوک چې د رشوت سره مینه کوی نو اور به د هغوی کورونه سوزوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36282, 'Job 15:35', 'Job', 15, 35, 'داسې خلق نورو ته د نقصان رسولو په سوچ کښې وى، هغوئ شېطانى کوى او د هغوئ زړونه د دوکې نه ډک وى.“', 'داسې خلق نورو ته د نقصان رسولو په سوچ کشې وی، هغوی شېطانی کوی او د هغوی زرونه د دوکې نه دک وی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_15_35.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36283, 'Esther 1:3', 'Esther', 1, 3, 'هغه د خپلې پاچاهۍ په درېم کال خپلو مامورینو او درباریانو ته مېلمستیا جوړه کړه. په مېلمستیا کې د فارس او ماد د لښکرو قوماندانان، مشران او والیان حاضر وو.', 'هغه د خپلې پاچاهی په درېم کال خپلو مامورینو او درباریانو ته مېلمستیا جوره کره. په مېلمستیا کې د فارس او ماد د لشکرو قوماندانان، مشران او والیان حاضر وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_1_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36284, 'Esther 1:4', 'Esther', 1, 4, 'د پوره شپږو میاشتو دپاره پاچا د خپلې پاچاهۍ زیاته شتمني، شان او شوکت او خپله شاهانه لویي نندارې ته وړاندې کړل.', 'د پوره شپزو میاشتو دپاره پاچا د خپلې پاچاهی زیاته شتمنی، شان او شوکت او خپله شاهانه لویی نندارې ته وراندې کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_1_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36285, 'Esther 1:5', 'Esther', 1, 5, 'وروسته له هغې پاچا ټولو خلکو ته که شتمن وو یا غریب، د شوش په بالاحصار کې د شاهي ماڼۍ د باغ په حوېلۍ کې مېلمستیا ورکړه او پوره اووه ورځې دې مېلمستیا دوام وکړ.', 'وروسته له هغې پاچا تولو خلکو ته که شتمن وو یا غریب، د شوش په بالاحصار کې د شاهی مانی د باغ په حوېلی کې مېلمستیا ورکره او پوره اووه ورجې دې مېلمستیا دوام وکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_1_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36286, 'Esther 1:6', 'Esther', 1, 6, 'حوېلۍ په اسماني او د سپین کتان په پردو باندې ښکلې شوې وه چې په بانجاني ښه کتاني رسیو باندې تړل شوې وې او د سپینو زرو په هغو کړیو کې ځای په ځای شوې وې چې د مرمرو په ستنو باندې ځوړندې وې. هغه تختونه چې د سرو او سپینو زرو څخه جوړ شوي وو، په هغې حوېلۍ کې چې په سپینو مرمرو، سور بخنو تیږو، صدف او فیروزې باندې فرش شوی ؤ، ایښودل شوي وو.', 'حوېلی په اسمانی او د سپین کتان په پردو باندې شکلې شوې وه چې په بانجانی شه کتانی رسیو باندې ترل شوې وې او د سپینو زرو په هغو کریو کې جای په جای شوې وې چې د مرمرو په ستنو باندې جورندې وې. هغه تختونه چې د سرو او سپینو زرو چخه جور شوی وو، په هغې حوېلی کې چې په سپینو مرمرو، سور بخنو تیزو، صدف او فیروزې باندې فرش شوی و، ایشودل شوی وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_1_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(36287, 'Esther 1:7', 'Esther', 1, 7, 'شراب یې د سرو زرو په پیالو کې ورکول او هرې پیالې یې د بلې پیالې نه فرق درلود. پاچا خلکو ته د شاهانه شرابو په ورکولو کې ډېر سخي ؤ', 'شراب یې د سرو زرو په پیالو کې ورکول او هرې پیالې یې د بلې پیالې نه فرق درلود. پاچا خلکو ته د شاهانه شرابو په ورکولو کې دېر سخی و', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_1_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
